const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const decisions={considering:'正在考虑',shortlisted:'重点候选',passed:'已排除',chosen:'已选定'},actions={not_contacted:'尚未联系',awaiting_reply:'等待房东回复',replied:'已收到回复',viewing_applying:'看房 / 申请中',completed:'当前流程完成'},rooms={'':'需要核实',studio:'Studio',ensuite:'独卫单间',shared:'合租',apartment:'整套公寓'},yn={'':'需要核实',yes:'是',no:'否'},bills={'':'需要核实',included:'包含',excluded:'不包含'};
const Q={bills:['租金包含哪些账单？','Which bills are included, and what additional costs apply?'],guarantor:['是否需要英国担保人？','Is a UK guarantor required, and are alternatives available?'],students:['是否接受国际学生申请？','Do you accept international student applicants?'],available_from:['何时可以入住？','When is the property available?'],tenancy:['最短租期和预付条件？','What are the minimum tenancy and upfront payment requirements?'],sharing:['是否允许计划人数合租？','What are the occupancy and unrelated sharer requirements?'],deposit:['押金及其他入住费用？','What deposit and other upfront costs are required?']};
let state=null,homes=[],project=localStorage.getItem('project')||'default',filter='all',search='',tab='overview',busy=false,dialogHome=null,selected=new Set(readLocal('compareSelection',[]));
function readLocal(k,d){try{return JSON.parse(localStorage.getItem(k)||'null')??d}catch{return d}}
function putLocal(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{notice('浏览器本地空间不足，请先保存草稿到工作台。')}}
const p=()=>state?.projects.find(x=>x.id===project),mine=()=>homes.filter(x=>x.project_id===project),get=id=>homes.find(h=>h.id===id),money=(value,currency='GBP')=>value==null?'待核实':currency+' '+Number(value).toLocaleString('zh-CN',{maximumFractionDigits:2}),date=t=>t?new Date(t).toLocaleString('zh-CN'):'尚无记录';
function notice(t){const el=$('#modal').open?$('#modalNotice'):$('#notice');el.textContent=t;el.hidden=false}
function clearNotice(){$('#notice').hidden=true;$('#modalNotice').hidden=true}
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json',Authorization:'Bearer '+state.token}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(path.startsWith('ai/')&&path!=='ai/config'?90000:10000)});const v=await r.json();if(!r.ok)throw Error(v.error||'操作失败');return v}
async function run(fn){if(busy)return;busy=true;document.body.classList.add('busy');try{await fn()}catch(e){notice(e.name==='TimeoutError'?'连接超时，请稍后重试。':e.message==='Failed to fetch'?'无法连接本地服务，请启动 UrHomi 后重试。':e.message)}finally{busy=false;document.body.classList.remove('busy')}}
async function load(){state=await api('bootstrap');if(!p())project=state.projects[0].id;homes=await api('homes');selected=new Set([...selected].filter(id=>get(id)));putLocal('compareSelection',[...selected]);render()}
async function mutate(id,data){const r=await api('homes/'+id,data);homes=await api('homes');render();return get(id)||r}
function route(){const [page,id]=location.hash.slice(1).split('?')[0].split('/');return {page:page||'housing',id}}
function go(page,id){location.hash=page+(id?'/'+id:'')}
function opts(values,v){return Object.entries(values).map(([key,label])=>`<option value="${esc(key)}" ${String(v??'')===key?'selected':''}>${esc(label)}</option>`).join('')}
function input(key,label,value,type='text',hint=''){return `<label>${label}<input name="${key}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" max="9999999" step="0.01"':''}>${hint?'<small>'+hint+'</small>':''}</label>`}
function select(key,label,values,value){return `<label>${label}<select name="${key}">${opts(values,value)}</select></label>`}
function badge(text,color=''){return `<span class="tag ${color}">${esc(text)}</span>`}
function source(h){let host='';try{host=new URL(h.url).hostname}catch{}const rm=/(^|\.)rightmove\.co\.uk$/.test(host),zp=/(^|\.)zoopla\.co\.uk$/.test(host);return `<span class="source-icon ${zp?'zoopla':rm?'':'manual'}">${zp?'Z':rm?'RM':'↗'}</span><span>${rm?'Rightmove':zp?'Zoopla':esc(h.source||'手动导入')}</span>`}
function verdict(h){const conflicts=h.assessment.fit.filter(r=>r.status==='conflict');return {title:conflicts.length?'有 '+conflicts.length+' 项条件冲突':'值得进一步核实',color:conflicts.length?'amber':'',text:conflicts.length?conflicts.map(r=>r.label).join('、'):h.assessment.next_step}}
function progress(){const a=mine(),steps=[[!!(p().budget&&p().move_in),'填写我的需求','needs'],[a.length>0,'保存喜欢的房源','queue'],[a.some(h=>h.draft||h.contacted_at),'咨询并核实','queue'],[a.some(h=>h.decision_status==='chosen'),'比较并作出决定','compare']];return `<div class="steps">${steps.map((s,i)=>`<a class="step ${s[0]?'done':''}" href="#${s[2]}"><i>${s[0]?'✓':i+1}</i>${s[1]}</a>`).join('')}</div>`}
const housingPages = {housing:'Housing Plan', queue:'Saved Homes', match:'Roommate Match', compare:'房源对比', channels:'找房渠道', neighborhood:'周边笔记'};
const profilePages = {profile:'Living Card', needs:'住房需求', ai:'咨询设置'};

function sectionNav(pages, page) {
  return `<nav class="section-nav" aria-label="当前栏目">${Object.entries(pages).map(([id,label]) =>
    `<a href="#${id}"${id===page?' aria-current="page"':''}>${label}${id==='compare'?'<span id="compareCount"></span>':''}</a>`).join('')}</nav>`;
}

function render() {
  if (!state) return;
  const {page,id}=route(), current=p();
  const area=page==='community'?'community':page in profilePages?'profile':'housing';
  $('#project').innerHTML=state.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===project?'selected':''}>${esc(x.name)}</option>`).join('');
  $('#breadcrumb').textContent={housing:'HOUSING PROJECT',community:'COMMUNITY',profile:'MY PROFILE'}[area];
  $('#modeBadge').textContent=current.is_demo?'流程演练 · 合成数据':'本地保存';
  $('#modeBadge').className='tag '+(current.is_demo?'amber':'');
  document.querySelectorAll('[data-nav]').forEach(a=>{
    if(a.dataset.nav===area) a.setAttribute('aria-current', 'true');
    else a.removeAttribute('aria-current');
  });
  const ids=[...selected].filter(id=>get(id)?.project_id===project);
  $('#compareBar').hidden=!ids.length||page==='compare'||!['queue','home'].includes(page);
  $('#compareBar').innerHTML=`<span>已选 ${ids.length} 套房源</span><button data-act="compare">开始对比 →</button><button class="text-button" data-act="clearCompare">清空</button>`;
  const views={housing:housingPlan,queue,match:roommateMatch,compare,home:()=>detail(id),community,profile,channels,neighborhood,needs,ai:aiSettings};
  const view=Object.prototype.hasOwnProperty.call(views,page)?views[page]:housingPlan;
  const nav=area==='housing'?sectionNav(housingPages,page==='home'?'queue':page):area==='profile'?sectionNav(profilePages,page):'';
  const demo=current.is_demo?'<div class="demo-banner">流程演练项目 · 当前房源、预算和回复示例均为合成数据。</div>':'';
  $('#main').innerHTML=demo+nav+view();
  if ($('#compareCount') && ids.length) $('#compareCount').textContent=ids.length;
}

function planCard(tone, icon, label, title, description, href, action) {
  return `<article class="plan-card ${tone}">
    <div class="plan-card-top"><span class="plan-icon" aria-hidden="true">${icon}</span><span class="eyebrow">${label}</span></div>
    <h2>${title}</h2><p>${description}</p>
    <a class="pill-link" href="#${href}">${action} <span aria-hidden="true">↗</span></a>
  </article>`;
}

function housingPlan() {
  const all=mine(), shortlisted=all.filter(h=>h.decision_status==='shortlisted').length;
  return `<section class="plan-hero">
    <div><span class="eyebrow">01 / YOUR HOUSING WORKSPACE</span>
    <h1>Housing Plan<span>.</span></h1>
    <p>一起住的人，想住的地方。把两件事放在同一张计划里。</p></div>
    <div class="hero-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></div>
  </section>
  <div class="plan-grid">
    ${planCard('mint','◎','01 / PEOPLE','Roommate Match','用示例滑卡探索你在意的作息和共享空间习惯。','match','试用室友滑卡')}
    ${planCard('cream','⌂','02 / HOMES','Saved Homes',`已收藏 ${all.length} 套房源，其中 ${shortlisted} 套重点候选。查看原始照片、价格和联系进度。`,'queue','查看已保存房源')}
  </div>
  <section class="lens-strip"><div class="plan-icon" aria-hidden="true">✦</div>
    <div><h2>Housing Lens</h2><p>在 Rightmove 或 Zoopla 用 Chrome 插件一键读取并保存房源。</p></div>
    <button class="quiet" data-act="plugin">查看插件用法 ↗</button>
  </section>`;
}

const roommateExamples=[
  {name:'示例 A',initial:'A',tone:'rose',summary:'工作日早睡，喜欢有规律的共享空间。',tags:['早睡早起','轮流清洁','在家做饭']},
  {name:'示例 B',initial:'B',tone:'lavender',summary:'晚上学习，周末喜欢邀请朋友来吃饭。',tags:['晚睡','周末聚餐','提前沟通访客']},
  {name:'示例 C',initial:'C',tone:'mint',summary:'在家时间较长，希望大家在安静时段戴耳机。',tags:['居家学习','安静时段','共享厨具']}
];
let roommateIndex=0, roommateChoices=[];
function roommateMatch() {
  const example=roommateExamples[roommateIndex];
  return `<div class="page-title"><div><span class="eyebrow">PEOPLE / 交互原型</span><h1>Roommate Match</h1><p>体验滑卡。资料为虚构示例，选择只在本次页面会话中保留。</p></div></div>
    <section class="match-stage" aria-label="室友滑卡原型">
      <div class="match-progress" role="status">${example?`示例 ${roommateIndex+1} / ${roommateExamples.length}`:'已浏览全部示例'}</div>
      ${example?`<article class="match-card ${example.tone}" data-swipe>
        <div class="match-avatar" aria-hidden="true">${example.initial}</div>
        <h2>${example.name}</h2><p>${example.summary}</p>
        <div class="profile-tags">${example.tags.map(t=>badge(t)).join('')}</div>
      </article>
      <div class="match-actions"><button class="quiet" data-act="roommateSkip">← 跳过</button><button data-act="roommateLike">感兴趣 →</button></div>`:
      `<article class="match-card lavender"><h2>试滑完成</h2><p>你标记了 ${roommateChoices.length} 张感兴趣的示例卡。</p><button data-act="roommateReset">重新体验</button></article>`}
    </section>`;
}

function chooseRoommate(interested, moveFocus=false) {
  const example=roommateExamples[roommateIndex];
  if(!example) return;
  if(interested) roommateChoices.push(example.name);
  roommateIndex++;
  render();
  if(moveFocus) $(roommateExamples[roommateIndex]?'[data-act="roommateLike"]':'[data-act="roommateReset"]').focus();
}

let swipeStart;
document.addEventListener('pointerdown',e=>{
  if(e.isPrimary && e.button===0 && e.target.closest('[data-swipe]')) swipeStart={id:e.pointerId,x:e.clientX,y:e.clientY};
});
document.addEventListener('pointercancel',()=>{swipeStart=undefined});
document.addEventListener('pointerup',e=>{
  const start=swipeStart;
  swipeStart=undefined;
  if(!start || start.id!==e.pointerId || route().page!=='match') return;
  const dx=e.clientX-start.x, dy=e.clientY-start.y;
  if(Math.abs(dx)>55 && Math.abs(dx)>Math.abs(dy)*1.4) chooseRoommate(dx>0);
});

function queue(){const all=mine(),list=all.filter(h=>(filter==='all'||filter==='shortlisted'&&h.decision_status==='shortlisted'||filter==='waiting'&&h.action_status==='awaiting_reply'||filter==='due'&&h.assessment.due||filter==='active'&&!['passed','chosen'].includes(h.decision_status))&&(!search||[h.title,h.address,h.source,h.notes].some(v=>String(v||'').toLowerCase().includes(search.toLowerCase()))));return `<div class="page-title"><div><span class="eyebrow">02 / HOMES</span><h1>Saved Homes</h1><p>从一套真实房源开始，慢慢找到适合你的生活。</p></div></div>${!all.length?'<div class="banner"><div><h3>先保存一套喜欢的房源</h3><p>打开 Rightmove / Zoopla 出租详情页 → 点击「保存到我的房源」 → 回到这里查看。</p></div><button data-act="plugin" class="quiet">使用插件</button></div>':''}<div class="stats"><div class="stat accent"><strong>${all.length}</strong><span>已保存房源</span></div><div class="stat"><strong>${all.filter(h=>h.decision_status==='shortlisted').length}</strong><span>重点候选</span></div><div class="stat"><strong>${all.filter(h=>h.action_status==='awaiting_reply').length}</strong><span>等待房东回复</span></div><div class="stat"><strong>${all.filter(h=>h.pending_reply||h.assessment.due).length}</strong><span>待确认回复 / 跟进到期</span></div></div><div class="toolbar"><div class="filters">${Object.entries({all:'全部房源',active:'正在考虑',shortlisted:'重点候选',waiting:'等待回复',due:'跟进到期'}).map(([k,t])=>`<button data-act="filter" data-value="${k}" class="${filter===k?'active':''}">${t}</button>`).join('')}</div><input id="search" class="search" placeholder="搜索房源标题、来源或备注" aria-label="搜索房源" value="${esc(search)}"></div>${list.length?'<div class="grid">'+list.map(card).join('')+'</div>':`<div class="empty"><div class="symbol">⌂</div><h2>${all.length?'没有符合筛选条件的房源':'从一套真实房源开始'}</h2><p>${all.length?'试试清除搜索或切换筛选。':'在 Rightmove 或 Zoopla 页面点击 UrHomi 保存；也可以手动输入原始链接。'}</p><div class="row"><button data-act="import">导入房源</button><button data-act="plugin" class="quiet">从插件保存</button></div></div>`}`}
function photo(h){let url='';try{const u=new URL(h.image_url);if(u.protocol==='https:'&&!u.username&&!u.password)url=u.href}catch{}return `<figure class="property-photo"><div class="photo-placeholder">${url?'图片加载中 / 不可用':'暂无原平台图片'}</div>${url?`<img src="${esc(url)}" alt="${esc(h.title)}" loading="lazy" referrerpolicy="no-referrer">`:''}<figcaption>${esc(h.source||'原平台')} · 图片版权归原权利人</figcaption></figure>`}
function card(h){return `<article class="home-card"><div class="card-gallery">${gallery(h)}</div><div class="card-top"><div class="source">${source(h)}</div>${badge(actions[h.action_status],'gray')}</div><h2><a href="#home/${h.id}">${esc(h.title)}</a></h2><p>${esc(h.address||'地址待核实')}</p><div class="subline">${h.bedrooms==null?'卧室数待核实':h.bedrooms===0?'Studio':esc(h.bedrooms)+' 间卧室'} · ${esc(rooms[h.room_type]||'房型待核实')}</div><div class="card-price"><strong>${money(h.price,h.currency)}</strong><small>${h.period==='week'?'每周':h.period==='month'?'每月':'周期待核实'} · 原平台报价</small></div><p>${badge(decisions[h.decision_status]||'已保存','gray')}</p><small>读取时间：${h.extracted_at?date(h.extracted_at):'未记录'} · 价格与在租状态请在原网站核实</small><p class="original-url">${esc(h.url)}</p><button data-act="original" data-id="${h.id}" class="quiet">返回原网站 ↗</button><div class="card-foot"><label class="check"><input data-compare="${h.id}" type="checkbox" ${selected.has(h.id)?'checked':''}>加入对比</label><button data-act="detail" data-id="${h.id}" class="secondary">查看房源 →</button></div></article>`}
function needs(){const n=p();return `<div class="page-title"><div><span class="eyebrow">MAKE IT PERSONAL</span><h1>先定义，什么适合你。</h1><p>这些信息会用于房源匹配与费用计算。暂不确定的条件可以留空。</p></div></div>${progress()}<div class="needs-summary"><form id="needsForm" class="panel"><div class="form-section"><h3>01 · 我的住房计划</h3>${input('name','住房项目名称',n.name)}${input('school','学校 / 实际校区',n.school,'text','用于记录目的地，当前不会自动计算路线。')}<div class="two">${input('move_in','计划入住日期',n.move_in,'date')}${input('stay_months','计划居住月数',n.stay_months,'number')}${select('room_type','房型偏好',{'':'不限 / 尚未确定',studio:'Studio',ensuite:'独卫单间',shared:'合租',apartment:'整套公寓'},n.room_type)}${input('party_size','一起租房的人数',n.party_size||1,'number','多人均摊需同时确认房源的报价对象。')}</div></div><div class="form-section"><h3>02 · 预算与申请条件</h3><div class="two">${input('budget','每人基础租金预算',n.budget,'number')}${select('currency','预算币种',{GBP:'GBP 英镑',USD:'USD 美元',EUR:'EUR 欧元',CNY:'CNY 人民币'},n.currency)}${select('period','预算周期',{month:'每月',week:'每周'},n.period)}${input('max_commute','可接受单程通勤（分钟）',n.max_commute,'number')}${select('has_guarantor','你是否有英国担保人',{'':'尚未确定',yes:'有',no:'没有'},n.has_guarantor)}</div></div><button>保存需求并更新所有分析</button><small>保存后重新计算当前项目的房源；不会改变联系状态。</small></form><aside><div class="card"><span class="eyebrow">YOUR HOUSING BRIEF</span><h2>为你保留未知，<br>也把冲突说清楚。</h2><p class="note">没有填写预算时，不会判断房源“符合预算”。没有路线数据时，不会给出猜测的通勤时间。</p><hr><p class="note">匹配分为：符合要求、条件冲突、需要核实。每个结果都能看到依据。</p></div><details class="key-details"><summary>插件连接密钥</summary><p class="note">仅填写到自己安装的 UrHomi 插件中，请勿分享。</p><input id="token" aria-label="插件连接密钥" readonly type="password" value="${esc(state.token)}"><button type="button" data-act="showToken" class="text-button">显示 / 隐藏密钥</button></details><button data-act="newProject" class="text-button">＋ 新建另一个住房项目</button></aside></div>`}
function detail(id){const h=get(id);if(!h||h.project_id!==project)return '<div class="empty"><h2>房源不在当前项目中</h2><p>请切换项目或返回清单。</p><a href="#queue">返回我的房源</a></div>';const a=h.assessment,v=verdict(h);return `<a class="back" href="#queue">← 返回我的房源</a>${gallery(h)}<div class="detail-title"><div class="source">${source(h)}${badge('规则分析 · 数据待核实','gray')}</div><h1>${esc(h.title)}</h1><p class="note">${esc(rooms[h.room_type]||'房型待核实')} · 原始链接保留 · 最近更新 ${date(h.updated_at)}</p></div><a class="text-button" href="#neighborhood">Explore this neighborhood · 整理区域信息 →</a><div class="detail-tabs">${Object.entries({overview:'房源概览',cost:'费用与条件',contact:'咨询与回复',history:'进展记录'}).map(([key,t])=>`<button data-act="detailTab" data-value="${key}" class="${tab===key?'active':''}">${t}</button>`).join('')}</div><div class="detail-layout"><div>${tab==='overview'?overview(h):tab==='cost'?costs(h):tab==='contact'?contact(h):history(h)}</div><aside><div class="card action-card"><span class="eyebrow">NEXT BEST STEP</span><h2>${esc(v.title)}</h2>${badge(actions[h.action_status],h.action_status==='awaiting_reply'?'amber':'gray')}<p>${esc(a.next_step)}</p><button data-act="enquiry" data-id="${id}">${h.contacted_at?'准备跟进消息':'准备英文咨询'}</button><button data-act="reply" data-id="${id}" class="secondary">${h.pending_reply?'确认待处理回复':'记录房东回复'}</button><button data-act="original" data-id="${id}" class="quiet">打开原房源 ↗</button><hr>${select('decision','我的决定',decisions,h.decision_status).replace('name="decision"',`id="decision" data-id="${id}"`)}<button data-act="edit" data-id="${id}" class="text-button">核实 / 补充房源信息</button><label class="check"><input data-compare="${id}" type="checkbox" ${selected.has(id)?'checked':''}>加入房源对比</label><p class="note">决定与联系记录分别保存。标记重点候选不会记录为已发送。</p></div></aside></div>`}
function overview(h){const a=h.assessment,c=a.cost;return `<details><summary>需要时查看辅助解读</summary>${aiCard(h)}</details><div class="three"><section class="card"><small>每人基础月租</small><div class="big-number">${money(c.rent_person,h.currency)}</div><small>不含未知费用</small></section><section class="card"><small>费用完整度</small><div class="big-number">${c.total_person==null?'待补充':'已可估算'}</div><small>${c.gaps.length?esc(c.gaps.join('、')):'使用你输入的已知金额'}</small></section><section class="card"><small>需求匹配</small><div class="big-number">${a.fit.filter(r=>r.status==='matched').length} 项</div><small>另有 ${a.fit.filter(r=>r.status==='conflict').length} 项冲突</small></section></div><section class="card"><h2>个人需求匹配</h2><p class="note">根据当前项目需求和已填房源信息逐项比较。</p>${a.fit.map(r=>`<div class="fit-row"><strong>${esc(r.label)}</strong><div>${badge({matched:'符合要求',conflict:'条件冲突',unknown:'需要核实'}[r.status],r.status==='conflict'?'red':r.status==='unknown'?'gray':'')}<p>${esc(r.reason)}</p></div></div>`).join('')}</section><section class="card"><h2>最值得先问的问题</h2>${Object.entries(Q).filter(([k])=>!h[k]).slice(0,3).map(([k,q],i)=>`<div class="question-row"><b>0${i+1}</b>${q[0]}</div>`).join('')||'<p>核心离散条件已填写，可继续核实押金和合租约定。</p>'}<button data-act="enquiry" data-id="${h.id}" class="text-button">带着这些问题准备咨询 →</button></section>${evidence(h)}`}
function costs(h){const c=h.assessment.cost;return `<section class="card"><span class="eyebrow">TRUE LIVING COST</span><h2>把租金和费用缺口分开看。</h2><div class="big-number">${money(c.total_person,h.currency)}</div><small>每人每月已知总费用 ${c.total_person==null?'· 当前不能确定完整总额':''}</small>${[['每人基础租金',c.rent_person],['每人额外账单',c.bills_person],['每人交通费用',c.transport_person]].map(([t,v])=>`<div class="money-breakdown"><span>${t}</span><strong>${money(v,h.currency)}</strong></div>`).join('')}<div class="callout ${c.gaps.length?'warning':''}">${c.gaps.length?'仍需补充：'+esc(c.gaps.join('、')):'金额完整，可用作当前填写条件下的比较。'}账单未知不会按免费计算。</div><p class="note">${h.period==='week'?'周租按 ×52÷12 换算。':''}${h.rent_basis==='whole'?'按整套报价及 '+(p().party_size||1)+' 人均摊；是否允许合租仍需核实。':h.rent_basis==='person'?'当前报价对象为每人。':'报价对象尚未明确，多人时不自动均摊。'}</p><button data-act="edit" data-id="${h.id}" class="secondary">补充费用数据</button></section><div class="two"><section class="card"><h3>签约前准备资金</h3><div class="big-number">${money(c.upfront,h.currency)}</div><p class="note">按原报价对象计算：押金 + 基础月租 × 预付月数。必须补齐这两项才能估算。</p></section><section class="card"><h3>最低租期内预计支出</h3><div class="big-number">${money(c.contract_person,h.currency)}</div><p class="note">每人月度总费用 × 已填最低租期月数；不把可退押金重复计入支出。</p></section></div><section class="card"><h2>申请与合同条件</h2><div class="money-breakdown"><span>接受国际学生</span><strong>${yn[h.students||'']}</strong></div><div class="money-breakdown"><span>需要英国担保人</span><strong>${yn[h.guarantor||'']}</strong></div><div class="money-breakdown"><span>租期原文</span><strong>${esc(h.tenancy||'需要核实')}</strong></div><div class="money-breakdown"><span>可入住日期</span><strong>${esc(h.available_from||'需要核实')}</strong></div></section>`}
function contact(h){return `<section class="card"><h2>咨询与核实，一步步推进。</h2><p>${badge(actions[h.action_status])}</p><div class="money-breakdown"><span>最近确认联系</span><strong>${date(h.contacted_at)}</strong></div><div class="money-breakdown"><span>最近收到回复</span><strong>${date(h.last_response_at)}</strong></div><div class="money-breakdown"><span>跟进提示时间</span><strong>${h.follow_up_at?date(h.follow_up_at):'未设置'}</strong></div><div class="row"><button data-act="enquiry" data-id="${h.id}">准备 / 编辑英文咨询</button><button data-act="reply" data-id="${h.id}" class="secondary">录入并确认回复</button></div><div class="callout">勾选中文问题 → 生成并编辑英文 → 复制 → 在原网站自行发送 → 回来确认已发送。</div><p class="note">可选 OpenAI 生成或本地模板，回复候选仍须逐项确认。生成、复制、打开页面均不会标记为已联系。</p></section><section class="card"><h3>已经推进到下一阶段？</h3><div class="row"><button data-act="progress" data-id="${h.id}" data-value="viewing_applying" class="quiet">记录为看房 / 申请中</button><button data-act="progress" data-id="${h.id}" data-value="completed" class="quiet">当前流程完成</button></div></section>${evidence(h)}`}
function evidence(h){return `<section class="card"><h3>信息来源与核实记录</h3>${Object.entries(h.field_sources||{}).map(([k,v])=>`<small>${esc(Q[k]?.[0]||k)} · ${esc(v.source)} · ${date(v.at)}</small><div class="evidence">${esc(v.text)}</div>`).join('')||'<p class="note">尚无经你确认的房东回复字段。</p>'}${Object.entries(h.extraction_sources||{}).map(([k,v])=>`<small>页面提取 · ${esc(v.source)} · 待自行核实</small><div class="evidence">${esc(v.text)}</div>`).join('')}${h.extraction_warnings?.length?'<div class="callout warning">'+h.extraction_warnings.map(esc).join('<br>')+'</div>':''}${h.notes?'<div class="evidence">备注：'+esc(h.notes)+'</div>':''}</section>`}
function history(h){const labels={refresh_media:'更新房源相册',edit:'核实 / 更新房源',decision:'更新住房决定',prepare:'生成咨询草稿',draft:'保存咨询草稿',contact:'用户确认已发送',reply:'记录进展',extract_reply:'提取待确认回复',confirm_reply:'确认回复字段',reply_text:'只保存回复原文',progress:'记录下一阶段进展',ai_extract_reply:'AI 提取待确认回复',ai_brief:'生成 AI 辅助解读'};return `<section class="card"><h2>每一步都有记录。</h2><p class="note">这里只展示本机记录，不代表第三方网站的发送回执。</p>${h.history.length?h.history.slice().reverse().map(e=>`<div class="timeline-entry"><small>${date(e.at)}</small><h3>${esc(labels[e.event]||e.event)} ${esc(decisions[e.value]||actions[e.value]||'')}</h3>${e.text?'<div class="evidence">'+esc(e.text)+'</div>':''}${e.fields?'<p class="note">已确认：'+Object.keys(e.fields).map(k=>esc(Q[k]?.[0]||k)).join('、')+'</p>':''}</div>`).join(''):'<p class="note">暂无联系进展。保存房源不会生成已联系记录。</p>'}</section>`}
function compare(){const list=mine().filter(h=>selected.has(h.id));if(list.length<2)return `<div class="page-title"><div><span class="eyebrow">SIDE BY SIDE</span><h1>放在一起，选择更清楚。</h1><p>从当前项目勾选 2–3 套房源，比较真实费用、条件和未知项。</p></div></div><div class="empty"><div class="symbol">▥</div><h2>还需要选择 ${2-list.length} 套房源</h2><p>已选 ${list.length} 套。未知信息会保留为待核实，不会据此给房源排名。</p><a href="#queue">返回清单选择 →</a></div>`;const rows=[['我的决定',h=>badge(decisions[h.decision_status])],['联系进度',h=>badge(actions[h.action_status],'gray')],['每人基础月租',h=>money(h.assessment.cost.rent_person,h.currency)],['每人月度总费用',h=>money(h.assessment.cost.total_person,h.currency)],['费用缺口',h=>esc(h.assessment.cost.gaps.join('、')||'已填写完整')],['签约前准备资金',h=>money(h.assessment.cost.upfront,h.currency)],['账单',h=>bills[h.bills||'']],['国际学生申请',h=>yn[h.students||'']],['英国担保人要求',h=>yn[h.guarantor||'']],['可入住日期',h=>esc(h.available_from||'需要核实')],['已知冲突',h=>esc(h.assessment.fit.filter(x=>x.status==='conflict').map(x=>x.label).join('、')||'未发现已知冲突')],['下一步',h=>esc(h.assessment.next_step)]];return `<div class="page-title"><div><span class="eyebrow">SIDE BY SIDE</span><h1>哪一套，更适合你的生活？</h1><p>比较相同口径的已知信息；币种不同时不换算或排名。</p></div><a href="#queue">← 调整候选</a></div><div class="compare-wrap"><table class="compare-table"><thead><tr><th>比较 ${list.length} 套候选</th>${list.map(h=>`<th><div class="source">${source(h)}</div><h3>${esc(h.title)}</h3><a href="#home/${h.id}">查看详细分析 →</a></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${label}</td>${list.map(h=>'<td>'+fn(h)+'</td>').join('')}</tr>`).join('')}<tr><td>推进决定</td>${list.map(h=>`<td><button data-act="shortlist" data-id="${h.id}" class="secondary">设为重点候选</button></td>`).join('')}</tr></tbody></table></div><div class="callout">先核实最可能改变决定的费用和申请条件，再选定。所有数字基于你输入或确认的数据，不代表平台或房东保证。</div>`}
function show(html,id=null){dialogHome=id;$('#modalBody').innerHTML=html;$('#modalNotice').hidden=true;if(!$('#modal').open)$('#modal').showModal()}
function importModal(){show(`<h2 class="dialog-title">把候选房源带进来。</h2><p class="dialog-intro">从插件导入可带上页面字段；手动输入链接时，未知信息保持空白。</p><div class="banner"><div><h3>已安装 UrHomi Chrome 插件？</h3><p>打开 Rightmove / Zoopla 详情页，点击 UrHomi → 保存到我的房源。</p></div><button data-act="plugin" class="quiet">查看步骤</button></div><form id="importForm"><label>原始房源链接（每行一个，最多 10 个）<textarea name="urls" required placeholder="https://www.rightmove.co.uk/properties/…&#10;https://www.zoopla.co.uk/to-rent/details/…/"></textarea></label><p class="note">本机不会在后台抓取网站。链接保存后，可通过插件或手动补充标题、价格和条件。</p><button>保存链接到当前项目</button></form>`)}
function pluginModal(){show(`<h2 class="dialog-title">在原网站看房，在这里作决定。</h2><p class="dialog-intro">网站与当前安装的 Chrome 插件使用同一份本机数据库。</p>${['在 Chrome 打开 Rightmove 或 Zoopla 的单套出租详情页。','点击页面右下角「保存到我的房源」，自动读取并保存资料。','保存成功后回到「我的房源」刷新，查看照片与报价。','首次使用先启动本地服务，再在插件点击「连接本机工作台」，通常无需复制密钥。'].map((t,i)=>`<div class="question-row"><b>0${i+1}</b>${t}</div>`).join('')}<div class="row"><a href="https://www.rightmove.co.uk/property-to-rent.html" target="_blank" rel="noopener noreferrer">打开 Rightmove ↗</a><a href="https://www.zoopla.co.uk/to-rent/" target="_blank" rel="noopener noreferrer">打开 Zoopla ↗</a></div><p class="note">安全验证或无法识别时，回到工作台手动补充，未知数据不会由系统猜测。</p>`)}
function editModal(id){const h=get(id);show(`<h2 class="dialog-title">核实房源信息</h2><p class="dialog-intro">请使用原页面或房东回复核实。没有数据的项目留空，0 仅用于已确认没有这项费用。</p><form id="listingForm"><input type="hidden" name="id" value="${h.id}">${input('title','房源标题',h.title)}${input('address','地址（原页面）',h.address)}${input('bedrooms','卧室数（Studio 填 0）',h.bedrooms,'number')}${input('url','原始链接',h.url,'url')}<div class="two">${input('price','基础租金',h.price,'number')}${select('currency','币种',{'':'未知',GBP:'GBP',USD:'USD',EUR:'EUR',CNY:'CNY'},h.currency)}${select('period','报价周期',{'':'未知',week:'每周',month:'每月'},h.period)}${select('rent_basis','报价对象',{'':'尚未核实',whole:'整套报价',person:'每人报价'},h.rent_basis)}${select('room_type','房型',rooms,h.room_type)}${input('available_from','可入住日期',h.available_from,'date')}${select('bills','账单是否包含',bills,h.bills)}${select('students','接受国际学生',yn,h.students)}${select('guarantor','需要英国担保人',yn,h.guarantor)}${input('tenancy','租期原文',h.tenancy)}${input('tenancy_months','最低租期月数',h.tenancy_months,'number')}${input('commute_minutes','已核实单程通勤分钟',h.commute_minutes,'number')}</div><hr><h3>费用补充</h3><p class="note">账单和押金按上面的报价对象填写；交通费用按每人填写。无需按网站默认规则推算押金。</p><div class="two">${input('bills_monthly','额外账单 / 月',h.bills_monthly,'number')}${input('transport_monthly','每人交通 / 月',h.transport_monthly,'number')}${input('deposit','已知押金金额',h.deposit,'number')}${input('prepaid_months','已知预付租金月数',h.prepaid_months,'number')}</div><label>备注 / 费用依据<textarea name="notes">${esc(h.notes)}</textarea></label><button>保存并重新分析</button></form>`,id)}
function localDraft(id){return readLocal('enquiry:'+id,null)}
function persistDraft(){if(!dialogHome||!$('#draft'))return;putLocal('enquiry:'+dialogHome,{text:$('#draft').value,questions:[...document.querySelectorAll('[data-question]:checked')].map(x=>x.value),tone:$('#tone').value});$('#draftHint').textContent='草稿已保存在此浏览器；点击保存草稿可同步到插件。'}
function enquiry(id){const h=get(id),d=localDraft(id),qs=d?.questions??h.questions??Object.keys(Q).filter(k=>!h[k]).slice(0,3);show(`<h2 class="dialog-title">${h.contacted_at?'准备跟进消息':'准备英文咨询'}</h2><p class="dialog-intro">${esc(h.title)} · ${p().is_demo?'流程演练（不实际发送）':'勾选中文问题，英文草稿由你确认后使用。'}</p><div class="question-grid">${Object.entries(Q).map(([k,q])=>`<label class="check"><input type="checkbox" data-question value="${k}" ${qs.includes(k)?'checked':''}>${q[0]}</label>`).join('')}</div><div class="two">${select('tone','语气',{friendly:'自然礼貌',formal:'正式'},d?.tone||'friendly').replace('name="tone"','id="tone"')}<div class="row"><button data-act="generate" data-id="${id}" type="button" class="secondary">${d?.text||h.draft?'重新生成英文草稿':'生成英文草稿'}</button></div></div><div class="row"><button data-act="aiEnquiry" data-id="${id}" class="secondary" ${state.ai?.enabled?'':'disabled'}>用 AI 生成英文咨询</button><a href="#ai" data-act="aiSettings">${state.ai?.enabled?'OpenAI · '+esc(state.ai.model):'先配置 AI'}</a></div><label>英文咨询（可编辑）<textarea id="draft" lang="en">${esc(d?.text??h.draft)}</textarea></label>${aiSuggestion(id)}<small id="draftHint">可用本地模板或 OpenAI；AI 调用会发送当前房源字段、相关需求和所选问题。生成不会记录为已联系。</small><div class="sticky-actions"><button data-act="saveDraft" data-id="${id}" class="quiet">保存草稿</button><button data-act="copy" data-id="${id}">复制英文咨询</button><button data-act="original" data-id="${id}" class="secondary">打开原房源 ↗</button></div><hr><p class="note">${p().is_demo?'演练模式可勾选下面选项模拟状态，不会向任何网站发消息。':'在原网站自行发送后，才勾选下面的确认。复制或打开网页不代表已发送。'}</p><label class="check"><input id="sent" type="checkbox">${p().is_demo?'我确认这是演练，模拟已发送':'我确认已经在原网站发送此咨询'}</label>${select('days','确认联系后的跟进提示',{2:'2 天后',3:'3 天后',5:'5 天后',0:'不提示'},'2').replace('name="days"','id="days"')}<button data-act="contact" data-id="${id}">已发送，记录联系</button>`,id)}
function replyModal(id,text){const h=get(id),pending=h.pending_reply,raw=text??pending?.text??readLocal('reply:'+id,'');show(`<h2 class="dialog-title">把回复变成可用的信息。</h2><p class="dialog-intro">${esc(h.title)} · 可用本地规则或 OpenAI 提取明确条件，候选先由你确认。</p><label>房东回复原文<textarea id="replyText">${esc(raw)}</textarea></label>${p().is_demo?'<button data-act="testReply" class="text-button">填入明确标注的测试回复</button>':''}<div class="row"><button data-act="extract" data-id="${id}">本地规则提取</button><button data-act="aiExtract" data-id="${id}" class="secondary" ${state.ai?.enabled?'':'disabled'}>用 AI 提取回复</button></div><p class="note">AI 提取会把这段回复发给 OpenAI；仅粘贴与租赁条件有关的内容。${state.ai?.enabled?'当前模型：'+esc(state.ai.model):'请先在 咨询设置中配置。'}</p><div id="replyCandidates">${pending&&raw===pending.text?candidates(h):''}</div>`,id)}
function candidates(h){const pending=h.pending_reply;return `<hr><h3>待确认结果</h3><p class="note">${pending.engine==='openai'?'OpenAI · '+esc(pending.model):'本地规则提取'}</p>${pending.summary_zh?'<div class="callout">'+esc(pending.summary_zh)+'</div>':''}<div class="evidence">${esc(pending.text)}</div><div class="check-list">${Object.entries(pending.fields).map(([k,v])=>`<label class="check"><input data-approved type="checkbox" value="${k}">${Q[k][0]} → ${esc((k==='bills'?bills:yn)[v])}${h[k]&&h[k]!==v?'（将覆盖原值）':''}</label>${pending.evidence?.[k]?'<div class="evidence">原文依据：'+esc(pending.evidence[k])+'</div>':''}`).join('')||'<p class="note">没有足够明确的字段。可以只保存回复原文，之后手动核实条件。</p>'}</div><p class="note">未确认前不会更新房源字段。只勾选准确的项目；未勾选项保持原值。</p><div class="sticky-actions"><button data-act="approve" data-id="${h.id}">确认所选并更新分析</button><button data-act="replyTextOnly" data-id="${h.id}" class="quiet">只保存回复原文</button></div>`}
async function saveDraft(id){persistDraft();const d=localDraft(id);if(!d)throw Error('请先填写草稿');const result=await mutate(id,{event:'draft',text:d.text,questions:d.questions});putLocal('enquiry:'+id,null);return result}
function aiSettings(){const a=state.ai||{};return `<div class="page-title"><div><span class="eyebrow">OPENAI CONNECTION</span><h1>让 AI 帮你读懂条件。</h1><p>主动调用，保留依据，由你确认。不会自动发送或更改住房决定。</p></div></div><div class="needs-summary"><form id="aiForm" class="panel"><h2>OpenAI API 设置</h2><p>${badge(a.enabled?'已启用':a.configured?'已配置 · 未启用':'尚未配置',a.enabled?'':'gray')}${a.last_test==='success'?badge('上次连接测试通过'):''}</p><label>API 密钥<input id="apiKey" name="api_key" type="password" autocomplete="off" spellcheck="false" placeholder="${a.configured?'已保留在本机服务中；不修改可留空':'sk-…'}"></label><small>不会回显或写入网页存储、插件、SQLite 或项目包。本次密钥只在服务内存中，重启服务后需重新填写。${a.key_source==='environment'?'当前使用本机环境变量中的密钥。':''}</small>${input('model','模型名称',a.model||'gpt-5-mini')}<p class="note">默认 gpt-5-mini，可填写账号可用、支持结构化输出的模型。接口固定为 OpenAI 官方 API。</p><label class="check"><input name="enabled" type="checkbox" ${a.enabled?'checked':''}>启用 OpenAI AI 功能</label><label class="check"><input name="consent" type="checkbox" ${a.enabled?'checked':''}>我同意在主动点击 AI 功能时，将当前房源字段、相关需求（含预算及担保条件）或我粘贴的回复发送给 OpenAI 处理，并了解可能产生 API 费用。</label><div class="sticky-actions"><button>保存本次配置</button><button data-act="aiTest" type="button" class="secondary" ${a.enabled?'':'disabled'}>测试连接</button><button data-act="aiClear" type="button" class="quiet">清除本次密钥并停用</button></div><p class="note">测试连接只发送 OK 连接检查，不含房源或个人资料。</p></form><aside><div class="card"><h2>先接入三件实用的事。</h2><p><strong>英文咨询</strong><br><small>根据问题和已填需求生成自然的草稿，可编辑。</small></p><p><strong>房东回复理解</strong><br><small>理解不同表述，提取候选字段，逐项保留原文依据。</small></p><p><strong>看房解读</strong><br><small>解释当前冲突、未知条件和建议下一步。</small></p><hr><p class="note">费用仍由确定规则计算，AI 解读不成为已确认事实。API 请求设为不保存响应；不代表服务商的所有数据留存规则均被关闭。</p><a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener noreferrer">在 OpenAI 平台创建 API 密钥 ↗</a></div></aside></div>`}
function aiCard(h){const b=h.ai_brief;return `<section class="card ai-card"><div class="toolbar"><div><span class="eyebrow">AI ASSISTED · YOU DECIDE</span><h2>AI 看房解读</h2></div>${state.ai?.enabled?`<button data-act="aiBrief" data-id="${h.id}" class="secondary">${b?'重新生成 AI 解读':'生成 AI 解读'}</button>`:'<button data-act="aiSettings" class="secondary">配置 OpenAI</button>'}</div><p class="note">会发送当前房源字段、相关需求与规则分析，不发送历史对话、备注或账号凭据。AI 不会修改房源条件或住房决定。</p>${b?`${h.ai_brief_stale?'<div class="callout warning">房源或需求已变更。以下是旧版 AI 解读，请重新生成。</div>':''}<p>${esc(b.summary_zh)}</p><div class="two"><div><h3>建议核实的问题</h3>${b.questions.map(t=>'<p class="note">· '+esc(t)+'</p>').join('')}</div><div><h3>建议下一步</h3>${b.next_steps.map(t=>'<p class="note">· '+esc(t)+'</p>').join('')}</div></div>${b.limitations.length?'<div class="callout">'+b.limitations.map(esc).join('<br>')+'</div>':''}<small>OpenAI · ${esc(b.model)} · ${date(b.at)} · 辅助意见，未经事实核验</small>`:'<div class="callout">AI 解读与已确认字段分开展示。未配置时，你仍可使用费用分析、本地模板和规则提取。</div>'}</section>`}
function aiSuggestion(id){const r=readLocal('aiSuggestion:'+id,null);return r?`<div id="aiDraftSuggestion" class="callout"><h3>待采用的 AI 咨询版本</h3><div class="evidence">${esc(r.message_en)}</div><button data-act="useAiDraft" data-id="${id}" class="secondary">采用这个 AI 版本</button></div>`:''}
async function aiWork(button,fn){const before=button.textContent;button.disabled=true;button.textContent='AI 正在处理…';notice('正在请求 OpenAI，通常需要一些时间。当前信息与联系状态保持原样。');try{return await fn()}finally{if(button.isConnected){button.disabled=false;button.textContent=before}}}
const acts={
 aiSettings:()=>{$('#modal').close();go('ai')},
 aiTest:async b=>aiWork(b,async()=>{await api('ai/test',{});state.ai=await api('ai/status');render();notice('OpenAI 连接测试通过；未发送房源或个人资料。')}),
 aiClear:async()=>{state.ai=await api('ai/config',{clear:true});render();notice('已清除本次密钥并停用 AI。')} ,
 aiBrief:async b=>aiWork(b,async()=>{await api('ai/brief',{id:b.dataset.id});homes=await api('homes');render();notice('AI 解读已生成，仅作辅助意见；房源字段与决定未修改。')}),
 aiEnquiry:async b=>{const id=b.dataset.id,before=$('#draft').value,tone=$('#tone').value,questions=[...document.querySelectorAll('[data-question]:checked')].map(x=>x.value);if(!questions.length)throw Error('请至少勾选一个问题');if(before.trim()&&!confirm('AI 草稿生成后将替换当前内容，继续？'))return;await aiWork(b,async()=>{const r=await api('ai/enquiry',{id,questions,tone});if(dialogHome===id&&$('#draft')&&$('#draft').value===before&&$('#tone').value===tone&&JSON.stringify([...document.querySelectorAll('[data-question]:checked')].map(x=>x.value))===JSON.stringify(questions)){$('#draft').value=r.message_en;persistDraft();notice('OpenAI 草稿已生成，可继续编辑。'+r.notes_zh)}else{putLocal('aiSuggestion:'+id,r);notice('AI 草稿已保留为待采用版本，重新打开此房源咨询后可查看；未覆盖你的新编辑。')}})},
 useAiDraft:b=>{const r=readLocal('aiSuggestion:'+b.dataset.id,null);if(!r)throw Error('没有待采用的版本');if($('#draft').value.trim()&&!confirm('采用后将替换当前草稿，继续？'))return;$('#draft').value=r.message_en;putLocal('aiSuggestion:'+b.dataset.id,null);$('#aiDraftSuggestion')?.remove();persistDraft()},
 aiExtract:async b=>{const id=b.dataset.id,text=$('#replyText').value;putLocal('reply:'+id,text);await aiWork(b,async()=>{await api('ai/reply',{id,text});homes=await api('homes');render();if(dialogHome===id&&$('#replyText'))replyModal(id,$('#replyText').value);notice('AI 已提取候选字段；请核对原文并勾选确认，尚未更新房源条件。')})},
 close:()=>$('#modal').close(),refresh:async()=>{await load();notice('已刷新，插件保存的房源与进度已同步。')},import:importModal,plugin:pluginModal,detail:b=>{tab='overview';go('home',b.dataset.id)},filter:b=>{filter=b.dataset.value;render()},detailTab:b=>{tab=b.dataset.value;render()},edit:b=>editModal(b.dataset.id),enquiry:b=>enquiry(b.dataset.id),reply:b=>replyModal(b.dataset.id),compare:()=>go('compare'),clearCompare:()=>{selected=new Set([...selected].filter(id=>get(id)?.project_id!==project));putLocal('compareSelection',[...selected]);render()},shortlist:async b=>{await mutate(b.dataset.id,{event:'decision',value:'shortlisted'});notice('已设为重点候选；联系状态未改变。')},progress:async b=>{await mutate(b.dataset.id,{event:'progress',value:b.dataset.value});notice('已记录进展。')},showToken:()=>{$('#token').type=$('#token').type==='password'?'text':'password'},
 demo:async()=>{const r=await api('demo',{});project=r.project_id;localStorage.setItem('project',project);filter='all';search='';await load();go('queue');notice('已进入独立流程演练项目，合成数据与真实项目分开保存。')},
 newProject:()=>show(`<h2 class="dialog-title">新建住房项目</h2><p class="dialog-intro">不同城市、学期或合租计划可以分开比较。</p><form id="newProjectForm">${input('name','项目名称','')}<button>创建项目</button></form>`),
 generate:b=>{const id=b.dataset.id,h=get(id),qs=[...document.querySelectorAll('[data-question]:checked')].map(x=>x.value);if(!qs.length)throw Error('请至少勾选一个中文问题');if($('#draft').value.trim()&&!confirm('重新生成将替换当前编辑内容，继续？'))return;$('#draft').value=($('#tone').value==='formal'?'Dear letting team,\n\n':'Hello,\n\n')+(h.contacted_at?'I am following up on my enquiry about ':'I am interested in ')+h.title+'.\n\n'+qs.map(k=>Q[k][1]).join('\n')+'\n\nThank you. I look forward to hearing from you.';persistDraft()},
 saveDraft:async b=>{await saveDraft(b.dataset.id);notice('草稿和问题选择已保存到本地工作台，可在插件重新读取此房源。')},
 copy:async()=>{persistDraft();const text=$('#draft').value;if(!text.trim())throw Error('请先生成或填写英文咨询');try{await navigator.clipboard.writeText(text);notice('英文咨询已复制，请在原网站自行发送。')}catch{throw Error('复制失败，请选中英文草稿手动复制。')}},
 contact:async b=>{if(!$('#sent').checked)throw Error('请仅在实际发送后勾选确认；演练项目可模拟确认。');const text=$('#draft').value;if(!text.trim())throw Error('咨询消息不能为空');const days=Number($('#days').value);await saveDraft(b.dataset.id);await mutate(b.dataset.id,{event:'contact',text,days});$('#modal').close();tab='contact';go('home',b.dataset.id);render();notice(p().is_demo?'演练联系状态已更新为等待回复，未实际发送。':'已记录你确认的联系时间，状态为等待回复。')},
 testReply:()=>{$('#replyText').value='[测试回复，非真实房东消息] Bills are not included. A UK guarantor is required. International students are welcome.';putLocal('reply:'+dialogHome,$('#replyText').value);$('#replyCandidates').replaceChildren()},
 extract:async b=>{const text=$('#replyText').value;putLocal('reply:'+b.dataset.id,text);const h=await mutate(b.dataset.id,{event:'extract_reply',text});replyModal(h.id,text)},
 approve:async b=>{const h=get(b.dataset.id);if($('#replyText').value!==h.pending_reply?.text)throw Error('回复已编辑，请重新提取再确认');const fields={};document.querySelectorAll('[data-approved]:checked').forEach(x=>fields[x.value]=h.pending_reply.fields[x.value]);if(!Object.keys(fields).length)throw Error('请至少勾选一个正确字段，或只保存原文');await mutate(h.id,{event:'confirm_reply',fields});putLocal('reply:'+h.id,'');$('#modal').close();tab='overview';render();notice('所选条件已确认，费用与个人匹配已重新计算。')},
 replyTextOnly:async b=>{const h=get(b.dataset.id);if($('#replyText').value!==h.pending_reply?.text)throw Error('回复已编辑，请重新提取后保存原文');await mutate(h.id,{event:'reply_text'});putLocal('reply:'+h.id,'');$('#modal').close();render();notice('已保存回复原文，房源条件保持原值。')}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;const act=b.dataset.act;if(act==='original'){e.preventDefault();const h=get(b.dataset.id);if(p()?.is_demo){notice('演练房源没有真实原网站，不打开或联系。');return}window.open(h.url,'_blank','noopener,noreferrer');return}if(act==='roommateSkip'||act==='roommateLike'){chooseRoommate(act==='roommateLike',true);return}if(act==='roommateReset'){roommateIndex=0;roommateChoices=[];render();$('[data-act="roommateLike"]').focus();return}if(acts[act]){e.preventDefault();run(()=>acts[act](b))}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;const start=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start)}if(e.target.id==='draft')persistDraft();if(e.target.id==='replyText'){putLocal('reply:'+dialogHome,e.target.value);$('#replyCandidates').replaceChildren()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-compare]')){const id=e.target.dataset.compare,count=[...selected].filter(id=>get(id)?.project_id===project).length;if(e.target.checked&&count>=3){e.target.checked=false;notice('每次最多比较 3 套房源。');return}e.target.checked?selected.add(id):selected.delete(id);putLocal('compareSelection',[...selected]);render()}if(e.target.id==='project'){project=e.target.value;localStorage.setItem('project',project);search='';filter='all';go('queue');render()}if(e.target.id==='decision')run(()=>mutate(e.target.dataset.id,{event:'decision',value:e.target.value}));if(e.target.matches('[data-question]')||e.target.id==='tone')persistDraft()});
document.addEventListener('submit',e=>{const form=e.target,formId=form.getAttribute('id');if(!['needsForm','newProjectForm','listingForm','importForm','aiForm'].includes(formId))return;e.preventDefault();const d=Object.fromEntries(new FormData(form));run(async()=>{if(formId==='aiForm'){const data={api_key:d.api_key,model:d.model,enabled:d.enabled==='on',consent:d.consent==='on'};state.ai=await api('ai/config',data);$('#apiKey').value='';render();notice('本次 AI 配置已保存到本机服务内存；可点击测试连接。')}else if(formId==='needsForm'){if(!Number.isInteger(Number(d.party_size))||Number(d.party_size)<1||Number(d.party_size)>20)throw Error('一起租房人数应为 1–20 的整数');await api('projects',{...d,id:project});await load();notice('需求已保存，当前项目的分析和对比已更新。')}else if(formId==='newProjectForm'){const n=await api('projects',{...d,currency:'GBP',period:'month'});project=n.id;localStorage.setItem('project',project);$('#modal').close();await load();go('needs')}else if(formId==='listingForm'){await mutate(d.id,{...d,event:'edit'});$('#modal').close();notice('房源信息已保存，分析已更新。')}else{const urls=[...new Set(d.urls.split(/\n/).map(v=>v.trim()).filter(Boolean))];if(!urls.length||urls.length>10)throw Error('请填写 1–10 个有效链接');const canonical=urls.map(raw=>{const u=new URL(raw);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('只支持不含登录凭据的 http/https 链接');const rm=/^(www\.)?rightmove\.co\.uk$/.test(u.hostname)&&u.pathname.match(/^\/properties\/(\d+)\/?$/),zp=/^(www\.)?zoopla\.co\.uk$/.test(u.hostname)&&u.pathname.match(/^\/to-rent\/details\/(\d+)\/?$/);if(rm)return 'https://www.rightmove.co.uk/properties/'+rm[1];if(zp)return 'https://www.zoopla.co.uk/to-rent/details/'+zp[1]+'/';u.hash='';return u.href});let added=0,duplicates=0;for(const url of new Set(canonical)){const r=await api('homes',{project_id:project,url,title:'待核实房源 · '+new URL(url).hostname});r.duplicate?duplicates++:added++}$('#modal').close();await load();go('queue');notice('已导入 '+added+' 套；已有 '+duplicates+' 套保留原进度。手动链接未提取页面信息，请继续补充。')}})});
window.addEventListener('hashchange',()=>{swipeStart=undefined;clearNotice();render();$('#main').focus({preventScroll:true});window.scrollTo({top:0})});window.addEventListener('focus',()=>{if(state&&!busy&&!$('#modal').open&&!['needs','ai','profile','community','neighborhood','match'].includes(route().page))run(load)});
run(async()=>{try{await load()}catch(e){$('#main').innerHTML='<div class="empty"><h2>工作台暂时无法连接</h2><p>请启动本机 UrHomi 服务，然后点击刷新。已有房源不会丢失。</p><button data-act="refresh">重新连接</button></div>';throw e}});

document.addEventListener('error',e=>{if(e.target.matches?.('.property-photo img,.gallery img'))e.target.remove()},true);

function gallery(h){const raw=h.images?.length?h.images:[{url:h.image_url}];const urls=[...new Set(raw.map(x=>typeof x==='string'?x:x.url).filter(x=>{try{const u=new URL(x);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}))];if(!urls.length)return `<div class="photo-placeholder gallery-empty">暂无原平台照片，请返回原网站查看</div>`;
return `<section class="gallery" aria-label="房源照片"><div class="gallery-track" tabindex="0" aria-label="左右滑动浏览照片">${urls.map((url,i)=>`<figure class="gallery-slide"><span class="photo-placeholder">照片加载失败，请到原网站查看</span><img src="${esc(url)}" alt="${esc(h.title)} · 照片 ${i+1}" ${i?'loading="lazy"':''} referrerpolicy="no-referrer"><figcaption>${i+1} / ${urls.length} · ${esc(h.source||'原平台')} · 图片版权归原权利人</figcaption></figure>`).join('')}</div><div class="gallery-controls"><button type="button" data-gallery="-1" ${urls.length<2?'hidden':''} aria-label="上一张照片">← 上一张</button><span>${urls.length>1?'左右滑动或点击切换 · '+urls.length+' 张照片':'仅保存了封面。请在原网站打开 Photos 相册后，用更新后的 Housing Lens 重新读取以补齐。'}</span><button type="button" data-gallery="1" ${urls.length<2?'hidden':''} aria-label="下一张照片">下一张 →</button></div></section>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-gallery]');if(!b)return;const track=b.closest('.gallery').querySelector('.gallery-track');const total=track.children.length;const current=Math.round(track.scrollLeft/track.clientWidth);const next=(current+Number(b.dataset.gallery)+total)%total;track.scrollTo({left:next*track.clientWidth,behavior:'smooth'})});
document.addEventListener('keydown',e=>{if(!e.target.matches('.gallery-track')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const track=e.target;track.scrollBy({left:track.clientWidth*(e.key==='ArrowRight'?1:-1),behavior:'smooth'})});

function channels(){return `<div class="page-title"><div><span class="eyebrow">THREE WAYS TO FIND YOUR PLACE</span><h1>More ways to feel at home.</h1><p>学校宿舍、商业学生公寓、私人租房，在同一个住房工作区里了解。</p></div></div><div class="editorial-grid">${[['01','University halls','学校官方宿舍','从学校官网的 Accommodation 页面了解申请资格、时间与房型。','先在 My Profile 记录学校，再前往学校官网核实。'],['02','Student residences','商业学生公寓 · PBSA','关注独卫、Studio、公共设施，以及账单与合同周期。','选择公寓官网核实库存和费用；当前未接入公寓数据库。'],['03','Private rentals','私人租房','在原平台浏览详情，用 Housing Lens 自动识别并保存到这里。','已支持 Rightmove / Zoopla 详情页抓取与去重。']].map(([n,t,z,d,f])=>`<article class="editorial-card"><span class="eyebrow">${n} / HOUSING CHANNEL</span><h2>${t}</h2><h3>${z}</h3><p>${d}</p><small>${f}</small>${channelLinks(n)}</article>`).join('')}</div><div class="banner"><div><h3>Keep the details together.</h3><p>已保存的真实照片、原始链接、报价和联系进度仍在 Saved Homes。</p></div><a href="#queue">查看我的房源 →</a></div>`}
function areaValue(){return workspace().area||''}
function neighborhood(){const area=areaValue();return `<div class="page-title"><div><span class="eyebrow">BEYOND THE FRONT DOOR</span><h1>Nearby</h1><p>从房源走向生活。选择城市或宽泛区域，整理你真正关心的问题。</p></div></div><section class="panel"><form id="areaForm"><label>你正在了解的宽泛区域<input name="area" maxlength="100" value="${esc(area)}" placeholder="例如 London · Bloomsbury"></label><button>保存关注区域</button></form><form id="areaNotesForm" class="area-notes"><label>区域研究笔记<textarea name="area_notes" maxlength="4000" placeholder="记录通勤核实结果、生活设施和待问问题">${esc(workspace().area_notes||'')}</textarea></label><button class="secondary">保存研究笔记</button></form><small>保存到本机工作区，不请求定位，不公开地址或住房计划。</small></section><div class="editorial-grid">${[['Everyday life','日常配套','核实超市、洗衣、医疗和生活设施的开放时间。'],['Getting around','通勤与连接','以实际校区和上课时段核实路线，当前不估算通勤时间。'],['Local knowledge','区域经验','区域内容与学生问答尚未上线。你可以先记录待核实事项。']].map(([t,z,d])=>`<article class="editorial-card"><span class="eyebrow">${esc(area||'YOUR AREA')}</span><h2>${t}</h2><h3>${z}</h3><p>${d}</p></article>`).join('')}</div><a class="text-button" href="#community">探索 Community →</a>`}
function community(){const scope=new URLSearchParams(location.hash.split('?')[1]||'').get('tab')||'campus';const labels={campus:['Campus','以学校为起点，连接新的生活。'],roommates:['Roommates','寻找生活节奏相合的室友。'],nearby:['Nearby','从宽泛区域，认识周边生活。']};const key=labels[scope]?scope:'campus';return `<div class="page-title"><div><span class="eyebrow">A LIFE TO BUILD</span><h1>Community</h1><p>从找到住所，到融入一座城市。</p></div></div><nav class="section-nav" aria-label="Community navigation">${Object.entries(labels).map(([k,v])=>`<a ${k===key?'aria-current="page"':''} href="#community?tab=${k}">${v[0]}</a>`).join('')}</nav><section class="community-stage ${{campus:'rose',roommates:'mint',nearby:'lavender'}[key]}"><span class="eyebrow">${labels[key][0]} / YOUR COMMUNITY BRIEF</span><h2>${labels[key][1]}</h2><p>${key==='campus'?'学校：'+esc(p().school||'尚未填写'):key==='nearby'?'关注区域：'+esc(areaValue()||'尚未选择'):'先在 Living Card 整理你的住房偏好。'}</p><p>公开社区正在筹备。你可以先保存自己的校园问题、室友需求或区域互助草稿。</p><a class="button-link" href="${key==='nearby'?'#neighborhood':'#profile'}">${key==='nearby'?'设置关注区域':'完善 Living Card'} →</a><small>以学校和主动选择的宽泛区域为基础，不显示精确位置。</small></section>${communityDraft(key)}`}
function profile(){const n=p(),w=workspace();return `<div class="page-title"><div><span class="eyebrow">MY PROFILE</span><h1>Living Card</h1><p>用 Living Card 整理你的住房计划，为未来的学生连接做好准备。</p></div></div><div class="profile-layout"><article class="living-card"><span class="eyebrow">URHOMI / LIVING CARD</span><div class="monogram">${esc((n.school||'U').slice(0,1).toUpperCase())}</div><h2>${esc(w.display_name||n.name)}</h2><p>${esc(n.school||'学校尚未填写')}</p><dl><dt>计划入住</dt><dd>${esc(n.move_in||'尚未确定')}</dd><dt>房型偏好</dt><dd>${esc(rooms[n.room_type]||'尚未确定')}</dd><dt>租金预算</dt><dd>${n.budget?money(n.budget,n.currency)+' / '+(n.period==='week'?'周':'月'):'尚未确定'}</dd></dl><p>${esc(w.bio||'从住房计划，开始介绍自己。')}</p><p>${esc(w.lifestyle||'生活习惯尚未填写')}</p><span class="tag">Private · 仅自己可见</span></article><section class="panel"><h2>Make it yours.</h2><form id="profileForm">${input('display_name','昵称',w.display_name||'')}<label>关于我<textarea name="bio" maxlength="1000" placeholder="学习阶段、兴趣与生活期待">${esc(w.bio||'')}</textarea></label><label>生活习惯与室友偏好<textarea name="lifestyle" maxlength="1000" placeholder="作息、安静时段、公共空间习惯">${esc(w.lifestyle||'')}</textarea></label><button>保存 Living Card</button></form><hr><p>Living Card 使用当前住房项目中已保存的需求。修改需求后，房源匹配与比较也会同步更新。</p><a class="button-link" href="#needs">编辑住房需求 →</a><hr><h3>你的可见范围</h3><p>当前资料仅用于本机住房工作区，尚未提供公开资料或社交连接功能。</p><a href="#ai">咨询与 AI 设置 ↗</a></section></div>`}
function workspace(){return state?.workspace?.[project]||{}}
function communityDraft(key){return `<section class="panel community-notes"><span class="eyebrow">PRIVATE DRAFT / 仅自己可见</span><h2>${{campus:'整理你的校园问题',roommates:'写下你的室友需求',nearby:'准备你的区域互助需求'}[key]}</h2><form id="communityDraftForm"><input type="hidden" name="draft_key" value="${key}_draft"><label>内容<textarea name="content" maxlength="4000" placeholder="仅保存草稿，不会发布或发送给任何人。">${esc(workspace()[key+'_draft']||'')}</textarea></label><button>保存私密草稿</button></form><small>草稿保存到本机工作区。当前尚未提供发布、成员搜索或私信。</small></section>`}
async function saveWorkspace(fields){const saved=await api('workspace',{project_id:project,fields});state.workspace=state.workspace||{};state.workspace[project]=saved;render();notice('已保存到本机工作区。')}
document.addEventListener('submit',e=>{const id=e.target.id;if(!['areaForm','areaNotesForm','profileForm','communityDraftForm'].includes(id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));run(()=>saveWorkspace(id==='communityDraftForm'?{[data.draft_key]:data.content}:data))});

function channelLinks(n){const links=n==='01'?[['#needs','记录学校与校区']]:n==='02'?[['https://www.unitestudents.com/','Unite Students'],['https://www.iqstudentaccommodation.com/','iQ Student Accommodation']]:[['https://www.rightmove.co.uk/student-accommodation.html','Rightmove Student'],['https://www.zoopla.co.uk/to-rent/student-accommodation/','Zoopla Student']];return '<div class="channel-links">'+links.map(([url,label])=>`<a href="${url}" ${url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${label} ↗</a>`).join('')+'</div>'}
